body:
Unexpected behaviour when loading test fixture into table making use of default value in `datetime` column.

This is a (multiple allowed):

* [x] bug
* [ ] enhancement
* [ ] feature-discussion (RFC)

* CakePHP Version: 3.3.9
Reproducible on CakePHP versions:
  * 3.3.9
  * 3.2.14
  * 3.1.14
  * 3.0.19
* Platform and Target: Tested on PHP 5.5.9, MySQL 5.5.50

### What you did

1. Create schema in MySQL - note `datetime` column with default value:

```
CREATE TABLE `foo` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `foo_string` varchar(45) DEFAULT NULL,
  `foo_datetime` datetime NOT NULL DEFAULT '2016-12-06 00:00:01',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
```

2. Create minimal table/entity implementations. e.g:

`src/Model/Table/FooTable.php`

```php
<?php
namespace App\Model\Table;

use Cake\ORM\Table;

class FooTable extends Table
{
    public function initialize(array $config)
    {
        parent::initialize($config);
        $this->table('foo');
    }
}
```

`src/Model/Entity/Foo.php`

```php
<?php
namespace App\Model\Entity;

use Cake\ORM\Entity;

class Foo extends Entity
{
    protected $_accessible = [
        '*' => true,
        'id' => false
    ];
}
```

3. Create test fixture. Note I have defined the default value for `foo_datetime`
   in the `$fields` declaration, but I haven't explicitly passed any value for
   `foo_datetime` in the `$records` declaration.

`tests/Fixture/FooFixture.php`

```php
<?php
namespace App\Test\Fixture;

use Cake\TestSuite\Fixture\TestFixture;

class FooFixture extends TestFixture
{
    public $table = 'foo';

    // @codingStandardsIgnoreStart
    public $fields = [
        'id' => ['type' => 'integer', 'length' => 11, 'unsigned' => false, 'null' => false, 'default' => null, 'comment' => '', 'autoIncrement' => true, 'precision' => null],
        'foo_string' => ['type' => 'string', 'length' => 45, 'null' => true, 'default' => null, 'collate' => 'utf8_general_ci', 'comment' => '', 'precision' => null, 'fixed' => null],
        'foo_datetime' => ['type' => 'datetime', 'length' => null, 'null' => false, 'default' => '2016-12-06 00:00:01', 'comment' => '', 'precision' => null],
        '_constraints' => [
            'primary' => ['type' => 'primary', 'columns' => ['id'], 'length' => []],
        ],
        '_options' => [
            'engine' => 'InnoDB',
            'collation' => 'utf8_general_ci'
        ],
    ];
    // @codingStandardsIgnoreEnd

    public $records = [
        [
            'id' => 1,
            'foo_string' => 'Lorem ipsum dolor sit amet',
        ],
    ];
}
```

4. Create a unit test which attempts to load the fixture.

`tests/TestCase/Model/Table/FooTableTest.php`

```php
<?php
namespace App\Test\TestCase\Model\Table;

use App\Model\Table\FooTable;
use Cake\ORM\TableRegistry;
use Cake\TestSuite\TestCase;

class FooTableTest extends TestCase
{
    public $Foo;

    public $fixtures = [
        'app.foo'
    ];

    public function setUp()
    {
        parent::setUp();
        $config = TableRegistry::exists('Foo') ? [] : ['className' => 'App\Model\Table\FooTable'];
        $this->Foo = TableRegistry::get('Foo', $config);
    }

    public function tearDown()
    {
        unset($this->Foo);
        parent::tearDown();
    }

    public function testFoo()
    {
        $this->markTestIncomplete('Not implemented yet.');
    }
}
```

5. Run tests:
```
vendor/bin/phpunit
```

### What happened

```
Exception: Unable to insert fixture "App\Test\Fixture\FooFixture" in "App\Test\TestCase\Model\Table\FooTableTest" test case: 
SQLSTATE[HY000]: General error: 1364 Field 'foo_datetime' doesn't have a default value in [/foo/bar/baz/vendor/cakephp/cakephp/src/TestSuite/Fixture/FixtureManager.php, line 337]
```

(line number is for CakePHP 3.3.9)

### What you expected to happen

```
OK, but incomplete, skipped, or risky tests!
Tests: 1, Assertions: 0, Incomplete: 1.
```

Expected behaviour would be that column `foo_datetime` is created with default
value `2016-12-06 00:00:01`, allowing the fixture to be loaded correctly rather
than no default value as indicated by error message.
